            chinup: ['امسك العقلة بقبضة معكوسة (راحة اليد ناحيتك) بعرض الكتفين|اسحب لحد ما دقنك تعدّي العقلة|انزل ببطء لامتداد كامل', 'نص حركة أو هز بالجسم', 'Grip the bar underhand at shoulder width|Pull until the chin clears the bar|Lower slowly to full extension', 'Half reps or swinging the body'],
            apull: ['ثبّت استيك على العقلة وحط ركبتك أو رجلك جواه|امسك العقلة بقبضة أمامية|اسحب لحد فوق العقلة|انزل بتحكم', 'سيب الاستيك يعمل الشغل كله بدل اللاتس', 'Loop a band over the bar and place a knee or foot in it|Grip the bar overhand|Pull above the bar|Lower with control', 'Letting the band do all the work instead of the lats'],
            pd: ['اقعد وثبّت فخديك تحت الدعامة|امسك البار أعرض من كتفك|اسحب لحد أعلى الصدر ولوحي الكتف يتقاربوا|ارجع ببطء لمدى كامل', 'ميل لورا كتير واستخدام وزن الجسم بدل اللاتس', 'Sit and secure your thighs under the pad|Grip the bar wider than shoulders|Pull to the upper chest, squeezing the shoulder blades|Return slowly to full stretch', 'Leaning too far back and using body weight instead of the lats'],
            cpd: ['امسك البار بقبضة أضيق من كتفك|اسحب لحد أعلى الصدر|اعصر اللاتس تحت|ارجع ببطء لامتداد كامل', 'شد بالساعدين بس بدل الظهر', 'Grip the bar narrower than shoulder width|Pull to the upper chest|Squeeze the lats at the bottom|Return slowly to a full stretch', 'Pulling only with the arms instead of the back'],
            vpull: ['ركّب مقبض V على البكرة|امسكه بقبضة محايدة واقعد ثابت|اسحب نحو منتصف الصدر|ارجع ببطء', 'ميل زيادة لورا أو رجوع سريع', 'Attach the V-handle to the pulley|Hold it with a neutral grip and sit steady|Pull to the mid-chest|Return slowly', 'Excessive lean-back or fast returns'],
            brow: ['انحنِ قدام وضهرك مستقيم وركبتيك مرنة|امسك البار بقبضة أعرض من كتفك|اسحب نحو السرة مع ثبات الجذع|انزل بتحكم', 'تقوّس الظهر أو هز الجسم لرفع الوزن', 'Hinge forward with a flat back and soft knees|Grip the bar wider than shoulders|Row to the navel with a steady torso|Lower under control', 'Rounding the back or jerking the weight up'],
            rgrow: ['انحنِ وضهرك مستقيم وامسك البار بقبضة معكوسة|اسحب نحو أسفل البطن|خلي الكوعين قريبين من الجسم|انزل بتحكم', 'تقوّس الظهر أو وقفة مستقيمة زيادة', 'Hinge with a flat back and grip the bar underhand|Row toward the lower stomach|Keep the elbows tucked|Lower under control', 'Rounding the back or standing too upright'],
            smrow: ['قف قدام سميث والبار مضبوط قرب الركبة|انحنِ وضهرك مستقيم|اسحب البار نحو البطن|انزل بتحكم', 'وقفة مستقيمة زيادة أو تقوّس الظهر', 'Stand at the Smith machine with the bar near knee height|Hinge with a flat back|Row the bar to the stomach|Lower under control', 'Standing too upright or rounding the back'],
            tbar: ['ثبّت طرف البار في زاوية أو جهاز تي-بار|انحنِ وضهرك مستقيم وامسك المقبض|اسحب نحو الصدر|انزل ببطء', 'تقوّس أسفل الظهر أو هز بالجسم', 'Wedge the bar end in a corner or T-bar unit|Hinge with a flat back and grab the handle|Row to the chest|Lower slowly', 'Rounding the lower back or jerking reps'],
            landrow: ['ثبّت طرف البار في زاوية أو لاندماين|قف جنب البار وامسك طرفه بإيد واحدة|اسحب نحو الورك مع ثبات الجذع|انزل ببطء', 'لف الجسم زيادة مع السحب', 'Wedge the bar end in a corner or landmine|Stand beside it and hold the end with one hand|Row to the hip with a steady torso|Lower slowly', 'Over-rotating the body while pulling'],
            crow: ['ثبّت صدرك على مسند الجهاز أو بنش مائل|امسك الوزن والذراعان متدليتان|اسحب نحو الورك مع عصر لوحي الكتف|انزل ببطء', 'رفع الصدر عن المسند مع كل عددة', 'Brace your chest on the pad or incline bench|Hold the weight with arms hanging|Row toward the hips, squeezing the shoulder blades|Lower slowly', 'Lifting the chest off the pad on every rep'],
            mrow: ['اضبط المقعد بحيث تكون المقابض قدام صدرك|اسحب بذراع واحدة والجذع ثابت|اعصر لوح الكتف ثانية|ارجع ببطء', 'لف الجذع مع كل سحبة', 'Set the seat so the handles sit at chest level|Row one arm while the torso stays still|Squeeze the shoulder blade briefly|Return slowly', 'Twisting the torso with each row'],
